interface.definition:
a!localVariables(
  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205586"(teamid: ri!teamid, assignedby:ri!assignedby, orgname:  ri!orgname, assignedon:ri!assignedon )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "APPROVE",
          submit: true,
          saveInto: {
            a!save(
              target: ri!button,
              value: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205572"
            )

          },
          loadingIndicator: true,
          style: "SOLID"
        ),
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "REJECT",
          submit: true,
          saveInto: {

            a!save(
              target: ri!button,
              value: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1205579"
            ),

          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target:ri!button,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "Form",
      secondaryText: "Enter your details",
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
